internal object DuaUkDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Аллахумма Біка Асбана", "О Аллах, через Тебе ми входимо в ранок і через Тебе ми входимо в вечір; Тобою ми живемо і Тобою вмираємо, і Тобі воскресіння.", "Вранці.", "Пророк ﷺ навчив сподвижників говорити сьогодні вранці та ввечері."),
        "dua_allahumma_bika_amsayna" to DuaText("Аллахумма Біка Амсайна", "О Аллах, через Тебе ми входимо у вечір і через Тебе ми входимо в ранок; Тобою ми живемо і Тобою вмираємо, і до Тебе повернення.", "Увечері.", "Пророк ﷺ навчив сподвижників говорити сьогодні вранці та ввечері."),
        "dua_afiyah_morning" to DuaText("Просять Афію", "О Аллах, я прошу Тебе пробачення і благополуччя в цьому світі і в майбутньому.", "Пророк ﷺ ніколи не залишав цю дуа ні вранці, ні ввечері.", "Нікому не дано нічого кращого, ніж добробут."),
        "dua_afini_fi_badani" to DuaText("Здоров'я тіла, слуху та зору", "О Аллах, даруй благополуччя моєму тілу. О Аллах, даруй благополуччя моєму слуху. О Аллах, даруй благополуччя моєму погляду. Немає Бога, крім Тебе.", "Тричі вранці і ввечері.", "Дуа для здоров'я та захисту почуттів."),
        "dua_ya_hayyu_aslih" to DuaText("Виправити всі мої справи", "О Вічноживий, Хранителю, з Твого милосердя я шукаю допомоги: упорядкуй усі мої справи і не залишай мене самому ні на мить ока.", "Пророк ﷺ порадив Фатімі (RA) вимовляти це вранці та ввечері.", "Просити Аллаха допомоги в будь-якій справі."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Тасбих Джувейрія (RA)", "Слава Аллаху, і вся хвала Йому — стільки, скільки Його створіння, скільки Йому подобається, дорівнює вазі Його Трону та чорнилу Його слів.", "Тричі вранці — вагоміше за години зікру.", "Вимовлення цих чотирьох фраз тричі переважує зікр від світанку до середини ранку."),
        "dua_salawat" to DuaText("Дуруд-е-Ібрагімі", "О Аллах, пошли молитви на Мухаммеда ﷺ і сім'ю Мухаммада, як Ти послав молитви на Ібрагіма (AS) і сім'ю Ібрагіма; You are Praiseworthy, Glorious. О Аллах, благослови Мухаммеда ﷺ і сім'ю Мухаммада, як Ти благословив Ібрагіма (AS) і сім'ю Ібрагіма; You are Praiseworthy, Glorious.", "Салават на Пророка ﷺ в молитві і в усі часи.", "На того, хто посилає салават один раз, Аллах посилає на нього десять милостей (Муслім 408)."),
        "dua_wudu_after" to DuaText("Після Вуду", "I bear witness that none has the right to be worshipped except Allah, alone, without partner, and that Muhammad ﷺ is His servant and Messenger. О Аллах, зроби мене серед тих, хто кається, і тих, хто очищається.", "Після завершення вуду.", "Для нього відкриті вісім воріт раю, щоб він увійшов, як забажає."),
        "dua_wudu_before" to DuaText("Перед Вуду", "В ім'я Аллаха.", "Коли починається вуду.", "Немає (повного) вуду для того, хто не згадує ім'я Аллаха над ним."),
        "dua_istiftah" to DuaText("Вступна молитва (Сана)", "Слава Тобі, о Аллах, і хвала Тобі. Благословенне ім'я Твоє, величність Твоя, і немає бога, крім Тебе.", "На початку молитви, відразу після вступного такбіру.", "Сунна відкриває дуа молитви."),
        "dua_ruku" to DuaText("В Руку", "Слава Господу моєму, Величному.", "Не менше трьох разів в руку.", "Сунна тасбіх руку."),
        "dua_sujood" to DuaText("У Суджуді", "Слава Господу моєму Всевишньому.", "Принаймні три рази в суджуді.", "Слуга знаходиться найближче до свого Господа під час прострації (Муслім 482)."),
        "dua_rising_ruku" to DuaText("Підйом з Руку", "Аллах чує того, хто славить Його. Наш Господи, Тобі належить уся хвала.", "Піднімаючись з руки і стоячи прямо.", "У кого «Раббана ва лакал-хамд» збігається з ангелами, його минулі гріхи прощені."),
        "dua_between_sajdas" to DuaText("Між двома седждами", "Господи, прости мене. Господи, прости мене.", "Сидячи між двома поклонами.", "Сунна дуа сидіння між поклонами."),
        "dua_before_salam_four" to DuaText("Притулок від чотирьох речей (перед саламом)", "О Аллах, я шукаю притулку в Тебе від покарання пекла, від покарання могили, від випробувань життя і смерті, і від зла випробування фальшивого Месії (Даджала).", "Після останнього ташаххуда і салавата, перед салямом.", "Пророк ﷺ наказав шукати притулку від цих чотирьох речей."),
        "dua_qunoot_witr" to DuaText("Qunoot у Witr", "О Аллах, проведи мене серед тих, кого Ти вивів, даруй мені благополуччя серед тих, кому Ти дарував благополуччя, візьми мене під свою опіку серед тих, кого Ти взяв під свою опіку, благослови мене в тому, що Ти дав, і захисти мене від зла того, що Ти постановив. Ти постановляєш, і ніхто не постановляє проти Тебе, і той, з ким Ти дружиш, ніколи не буде принижений. Blessed and Exalted are You, our Lord.", "У молитві witr — Пророк ﷺ навчив цьому Хасана ібн Алі (RA).", "Сунна кунут witr. (Серед ханафітів «Allahumma inna nasta'inuka» також добре відоме.)"),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma Inna Nasta'inuka)", "О Аллах, ми шукаємо Твоєї допомоги і Твого прощення, ми віримо в Тебе і покладаємося на Тебе, ми прославляємо Тебе найкращим чином, ми дякуємо Тобі і не є невдячними, і ми залишаємо тих, хто не кориться Тобі. О Аллах, Тобі єдиному ми поклоняємося, Тобі ми молимось і вклоняємося, до Тебе поспішаємо і прагнемо, ми сподіваємося на Твою милість і боїмося Твого покарання. напевно Твоє покарання досягне невіруючих.", "In witr — практика ханафітів.", "Повідомлено від Умара (RA) у кунуті."),
        "dua_sleep_aslamtu" to DuaText("Останні слова перед сном", "О Аллах, я підкоряюся Тобі, довіряю Тобі свою справу і віддаю свою спину Твоєму захисту, з надії на Тебе і страху перед Тобою. Немає притулку і втечі від Тебе, крім Тебе. Я вірю в Твою Книгу, яку Ти відкрив, і в Твого Пророка, якого Ти послав.", "Після вуду лежачи на правому боці — останні слова перед сном.", "Якщо він помре тієї ночі, він помре на фітрі (іслам)."),
        "dua_waking_night" to DuaText("Прокидаючись вночі", "Ніхто не гідний поклоніння, крім Аллаха, єдиного, без партнера. Його влада і хвала, і Він має владу над усім. Вся хвала Аллаху, слава Аллаху, ніхто не гідний поклоніння, крім Аллаха, Аллах є найбільшим, і немає сили та сили, крім Аллаха. О Аллах, прости мене.", "При пробудженні вночі.", "Його дуа відповідає, і якщо він робить вуду і молиться, його молитва приймається."),
        "dua_hamm_ibn_masud" to DuaText("Дуа для печалі (Ібн Масуд)", "О Аллах, я Твій слуга, син Твого слуги, син Твоєї служниці. Чуб мій у руці Твоїй, наказ Твій надо мною виконується, і наказ Твій щодо мене справедливий. Я прошу Тебе під кожним Твоїм іменем, яким Ти назвав Себе, або відкрив у Твоїй Книзі, або навчив будь-якому зі Твоїх творінь, або зберігав при собі в знанні невидимого, щоб Ти зробив Коран джерелом мого серця, світлом моїх грудей, видаленням мого смутку і відходом від мого занепокоєння.", "У горі та біді Аллах замінює горе радістю.", "Аллах усуває його тривогу і горе і дарує йому радість замість них."),
        "dua_difficulty_sahl" to DuaText("Коли щось складно", "О Аллах, ніщо не є легким, крім того, що Ти робиш легким, і Ти робиш важке легким, якщо бажаєш.", "Коли щось здається важким.", "Легкість на іспитах і важких завданнях."),
        "dua_musibah" to DuaText("Після лиха (Істірья)", "Ми належимо Аллаху і до Нього ми повернемося. О Аллах, винагороди мене за мою скорботу і заміни мені її чимось кращим.", "При будь-якій втраті чи нещасті.", "Аллах напевно дає щось краще — Умм Салама (RA) була дана Пророку ﷺ."),
        "dua_debt" to DuaText("Для звільнення від боргів", "О Аллах, досить мені того, що Ти зробив законним проти того, що Ти зробив незаконним, і своєю щедрістю зроби мене незалежним від усіх, крім Тебе.", "Для погашення боргу — вчив Алі (RA).", "Навіть якщо борг схожий на гору, Аллах погасить його."),
        "dua_anger" to DuaText("Коли сердитий", "Я шукаю притулку в Аллаха від шайтана, проклятого.", "Коли злий.", "Пророк ﷺ сказав: якщо він скаже це, його гнів піде."),
        "dua_waswasa" to DuaText("Проти васваси у вірі", "Я вірю в Аллаха і Його Посланців.", "Коли сатанинські нашіптування про віру приходять.", "Коли прийде шепіт, скажіть це і зупиніться на цьому (а також шукайте притулку в Аллаха)."),
        "dua_travel_full" to DuaText("Повне прохання про подорожі", "О Аллах, ми просимо Тебе на цій дорозі про праведність і благочестя, а також про вчинки, які подобаються Тобі. О Аллах, полегши нам цю подорож і скороти її відстань. О Аллах, Ти є Супутником у дорозі і Охоронцем родини.", "Вирушаючи в подорож, після «Subhanalladhi sakhkhara».", "Повна сунна подорож дуа."),
        "dua_return_travel" to DuaText("Повернення з подорожей", "Ми повертаємось, каємося, поклоняємось і прославляємо нашого Господа.", "По поверненні з подорожі.", "Пророк ﷺ сказав це, повертаючись із подорожі."),
        "dua_farewell_traveller" to DuaText("Прощання з подорожнім", "Я довіряю Аллаху вашу релігію, вашу довіру і результат ваших справ.", "При прощанні з подорожнім.", "Те, що довірено Аллаху, ніколи не втрачається."),
        "dua_entering_town" to DuaText("Зупинка в місці", "Я шукаю притулку в досконалих словах Аллаха від зла всього, що Він створив.", "При зупинці в місці або приїзді в нове місто.", "Ніщо не зашкодить йому, поки він не піде звідти."),
        "dua_boarding_ship" to DuaText("Посадка на судно / транспортний засіб", "В ім'я Аллаха його плавання і його стоянка. Воістину, мій Господь Прощає, Милосердний.", "При посадці на корабель або транспортний засіб — слова пророка Нуха (AS).", "Аят Корану — дуа ковчега Нуха (AS)."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Істігфар з Хайюль-Кайюмом", "Я шукаю прощення в Аллаха, крім Якого немає Бога, Вічно Живого, Хранителя, і я звертаюся до Нього з покаянням.", "За покаяння.", "Його гріхи прощаються, навіть якщо він утік з поля бою."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir Warham", "Мій Господи, прости і помилуй, бо Ти найкращий із тих, хто виявляє милосердя.", "Коранічне дуа — для прощення та милосердя.", "Останній аят сури аль-Мумінун."),
        "dua_majlis_kaffarah" to DuaText("Каффарат аль-Меджліс", "Слава Тобі, о Аллах, і хвала Тобі. Я свідчу, що немає Бога, крім Тебе. Прошу Твого прощення і звертаюся до Тебе з покаянням.", "Під час вставання зі зборів.", "Це стає спокутуванням за все неправильне, сказане на зібранні."),
        "dua_jami_forgiveness" to DuaText("Всебічне прощення", "О Аллах, прости мені мої помилки, моє невігластво, мою надмірність у моїх справах і все те, що Ти знаєш краще за мене.", "Повна дуа Пророка ﷺ.", "Пророк ﷺ використовував цю дуа."),
        "dua_parents_nuh" to DuaText("Дуа Нух (AS) для батьків", "Господи мій, прости мені, моїм батькам, тому, хто віруючим увійде в мій дім, і всім віруючим чоловікам і віруючим жінкам.", "Для батьків і віруючих.", "Дуа пророка Нуха (AS)."),
        "dua_shukr_parents" to DuaText("Подяка за батьків і праведних нащадків", "Мій Господи, дай мені бути вдячним за Твою милість, яку Ти дарував мені та моїм батькам, і робити добрі вчинки, які приємні Тобі, і зробити моїх нащадків праведними. Я звертаюся до Тебе з покаянням і я серед тих, хто підкоряється.", "Коранічний дуа досягнення сорока років.", "Вдячність, добрі справи і праведність своїх дітей — все в одному дуа."),
        "dua_intimacy" to DuaText("До подружніх стосунків", "В ім'я Аллаха. О Аллах, утримай Шайтана від нас і утримай Шайтана від того, що (дітей) Ти даруєш нам.", "До подружніх відносин.", "Якщо дитина засуджена, шайтан ніколи не завдасть їй шкоди."),
        "dua_ibrahim_children_protection" to DuaText("Охорона дому та дітей", "Мій Господи, зроби це місто безпечним і утримай мене та моїх дітей від поклоніння ідолам.", "Дуа пророка Ібрагіма (AS) — за безпеку міста та його дітей.", "Дуа за непохитне ставлення до таухіду."),
        "dua_drinking_milk" to DuaText("При вживанні молока", "О Аллах, благослови це для нас і дай нам більше цього.", "При вживанні молока.", "Молока вистачає і як їжу, і як питво."),
        "dua_iftar_host" to DuaText("Під час розговіння з іншими", "Нехай з тобою розговляються постники, хай праведники їдять твою їжу, а ангели нехай моляться за тебе.", "Коли розговляються у когось вдома.", "Дуа Пророка ﷺ для господаря."),
    )
}
